pool_event.deleted = 0

    AND pool_event.server_submit_time >= #{reqVO.submittedAtStart}
    AND pool_event.server_submit_time < #{reqVO.submittedAtEnd}


    AND pool_event.actual_employee_id = #{reqVO.employeeUserId}


    AND pool_event.actual_employee_id IN

        #{employeeUserId}



    AND pool_event.process_id = #{reqVO.processId}


    AND pool_event.process_id IN

        #{authorizedProcessId}



    AND pool_event.route_process_id IN

        #{authorizedRouteProcessId}



    AND pool_event.device_id = #{reqVO.deviceId}


    AND pool_event.template_type = #{reqVO.templateType}


    AND pool_event.event_type = #{reqVO.eventType}


    AND pool_event.report_output_quantity > 0


    AND pool_event.work_order_id = #{reqVO.workOrderId}


    AND work_order.code LIKE CONCAT('%', #{reqVO.workOrderCode}, '%')


    AND work_order.product_id = #{reqVO.productId}


    AND (
        product_item.code LIKE CONCAT('%', #{reqVO.productKeyword}, '%')
        OR product_item.name LIKE CONCAT('%', #{reqVO.productKeyword}, '%')
    )


    AND pqc_task.inspection_type = #{reqVO.inspectionType}


    AND pqc_task.round_no = #{reqVO.roundNo}




            AND (latest_submission_review.review_status IS NULL OR latest_submission_review.review_status = 'PENDING')


            AND latest_submission_review.review_status = #{reqVO.submissionReviewStatus}




    AND pool_event.event_type = 'PRODUCTION_SUBMIT'
    AND pool_event.report_management_status IN (
        'UNALLOCATED', 'PARTIALLY_ALLOCATED', 'PENDING_RELEASE'
    )


    AND pool_event.event_type = 'PRODUCTION_SUBMIT'


    AND pool_event.event_type = 'PQC_INSPECTION'
    AND (
        latest_submission_review.review_status IS NULL
        OR latest_submission_review.review_status <> 'APPROVED'
    )
    AND NOT EXISTS (
        SELECT 1
        FROM mes_pro_process_pool_active_order_release_application release_application
        INNER JOIN mes_pro_edhr_release_transaction release_transaction
          ON release_transaction.id = release_application.release_transaction_id
         AND release_transaction.tenant_id = release_application.tenant_id
         AND release_transaction.deleted = 0
         AND release_transaction.release_status = 'RELEASED'
        WHERE release_application.tenant_id = pqc_task.tenant_id
          AND release_application.active_order_id = pqc_task.active_order_id
          AND release_application.deleted = 0
    )


    AND pool_event.event_type = 'PQC_INSPECTION'
    AND latest_submission_review.review_status = 'APPROVED'

mapper.select:
SELECT FROM mes_pro_process_pool_event pool_event LEFT JOIN mes_pro_work_order work_order ON work_order.id = pool_event.work_order_id AND work_order.tenant_id = pool_event.tenant_id AND work_order.deleted = 0
LEFT JOIN mes_pro_process process ON process.id = pool_event.process_id AND process.tenant_id = pool_event.tenant_id AND process.deleted = 0 LEFT JOIN mes_qa_inspection_regulation_process qa_process ON qa_process.id = pool_event.qa_process_id AND qa_process.tenant_id = pool_event.tenant_id AND qa_process.deleted = 0 LEFT JOIN mes_md_workstation workstation ON workstation.id = pool_event.workstation_id AND workstation.tenant_id = pool_event.tenant_id AND workstation.deleted = 0 LEFT JOIN mes_pro_process_pool_pqc_record pqc ON pqc.event_id = pool_event.id AND pqc.tenant_id = pool_event.tenant_id AND pqc.deleted = 0 LEFT JOIN ( SELECT review_copy.tenant_id, review_copy.event_id, COUNT(DISTINCT review_copy.id) AS review_copy_count, MAX(review_copy.review_status) AS review_status, COALESCE(SUM(review_copy_field_stat.field_count), 0) AS field_count FROM mes_pro_process_pool_review_copy review_copy LEFT JOIN ( SELECT tenant_id, review_copy_id, COUNT(1) AS field_count FROM mes_pro_process_pool_review_copy_field WHERE deleted = 0 GROUP BY tenant_id, review_copy_id ) review_copy_field_stat ON review_copy_field_stat.review_copy_id = review_copy.id AND review_copy_field_stat.tenant_id = review_copy.tenant_id WHERE review_copy.deleted = 0 GROUP BY review_copy.tenant_id, review_copy.event_id ) review_copy_summary ON review_copy_summary.event_id = pool_event.id AND review_copy_summary.tenant_id = pool_event.tenant_id
LEFT JOIN ( SELECT tenant_id, event_id, CONCAT('原始记录已修改 ', COUNT(1), ' 次') AS summary FROM mes_pro_process_pool_event_revision WHERE deleted = 0 AND revision_status = 'EFFECTIVE' GROUP BY tenant_id, event_id ) revision_summary ON revision_summary.event_id = pool_event.id AND revision_summary.tenant_id = pool_event.tenant_id WHERE ORDER BY pool_event.server_submit_time DESC, pool_event.id DESC LIMIT #{offset}, #{reqVO.pageSize}

SELECT FROM mes_pro_process_pool_event pool_event LEFT JOIN mes_pro_work_order work_order ON work_order.id = pool_event.work_order_id AND work_order.tenant_id = pool_event.tenant_id AND work_order.deleted = 0
LEFT JOIN mes_pro_process process ON process.id = pool_event.process_id AND process.tenant_id = pool_event.tenant_id AND process.deleted = 0 LEFT JOIN mes_qa_inspection_regulation_process qa_process ON qa_process.id = pool_event.qa_process_id AND qa_process.tenant_id = pool_event.tenant_id AND qa_process.deleted = 0 LEFT JOIN mes_md_workstation workstation ON workstation.id = pool_event.workstation_id AND workstation.tenant_id = pool_event.tenant_id AND workstation.deleted = 0 LEFT JOIN mes_pro_process_pool_pqc_record pqc ON pqc.event_id = pool_event.id AND pqc.tenant_id = pool_event.tenant_id AND pqc.deleted = 0 LEFT JOIN ( SELECT review_copy.tenant_id, review_copy.event_id, COUNT(DISTINCT review_copy.id) AS review_copy_count, MAX(review_copy.review_status) AS review_status, COALESCE(SUM(review_copy_field_stat.field_count), 0) AS field_count FROM mes_pro_process_pool_review_copy review_copy LEFT JOIN ( SELECT tenant_id, review_copy_id, COUNT(1) AS field_count FROM mes_pro_process_pool_review_copy_field WHERE deleted = 0 GROUP BY tenant_id, review_copy_id ) review_copy_field_stat ON review_copy_field_stat.review_copy_id = review_copy.id AND review_copy_field_stat.tenant_id = review_copy.tenant_id WHERE review_copy.deleted = 0 GROUP BY review_copy.tenant_id, review_copy.event_id ) review_copy_summary ON review_copy_summary.event_id = pool_event.id AND review_copy_summary.tenant_id = pool_event.tenant_id
LEFT JOIN ( SELECT tenant_id, event_id, CONCAT('原始记录已修改 ', COUNT(1), ' 次') AS summary FROM mes_pro_process_pool_event_revision WHERE deleted = 0 AND revision_status = 'EFFECTIVE' GROUP BY tenant_id, event_id ) revision_summary ON revision_summary.event_id = pool_event.id AND revision_summary.tenant_id = pool_event.tenant_id WHERE pool_event.deleted = 0 AND pool_event.id = #{id}

SELECT allocation.event_id AS eventId, allocation.id AS allocationId, allocation.active_order_id AS activeOrderId, allocation.work_order_id AS workOrderId, work_order.code AS workOrderCode, allocation.allocated_quantity AS allocatedQuantity, CASE WHEN process_snapshot.planned_quantity_snapshot IS NULL THEN NULL ELSE GREATEST( COALESCE(order_process_allocation.total_allocated_quantity, 0) - process_snapshot.planned_quantity_snapshot, 0 ) END AS overageQuantity, CASE WHEN process_snapshot.planned_quantity_snapshot IS NULL THEN NULL WHEN COALESCE(order_process_allocation.total_allocated_quantity, 0) > process_snapshot.planned_quantity_snapshot THEN TRUE ELSE FALSE END AS needsAdjustment, CASE WHEN EXISTS ( SELECT 1 FROM mes_pro_process_pool_active_order_release_application release_application INNER JOIN mes_pro_edhr_release_transaction release_transaction ON release_transaction.id = release_application.release_transaction_id AND release_transaction.tenant_id = release_application.tenant_id AND release_transaction.deleted = 0 AND release_transaction.release_status = 'RELEASED' WHERE release_application.tenant_id = allocation.tenant_id AND release_application.active_order_id = allocation.active_order_id AND release_application.deleted = 0 ) THEN TRUE ELSE FALSE END AS released FROM mes_pro_process_pool_report_allocation allocation LEFT JOIN mes_pro_work_order work_order ON work_order.id = allocation.work_order_id AND work_order.tenant_id = allocation.tenant_id AND work_order.deleted = 0 LEFT JOIN mes_pro_process_pool_active_order_process_snapshot process_snapshot ON process_snapshot.active_order_id = allocation.active_order_id AND process_snapshot.route_process_id = allocation.route_process_id AND process_snapshot.process_id = allocation.process_id AND process_snapshot.tenant_id = allocation.tenant_id AND process_snapshot.deleted = 0 LEFT JOIN ( SELECT tenant_id, active_order_id, route_process_id, process_id, SUM(allocated_quantity) AS total_allocated_quantity FROM mes_pro_process_pool_report_allocation WHERE deleted = 0 AND lifecycle_status = 'CURRENT' GROUP BY tenant_id, active_order_id, route_process_id, process_id ) order_process_allocation ON order_process_allocation.active_order_id = allocation.active_order_id AND order_process_allocation.route_process_id = allocation.route_process_id AND order_process_allocation.process_id = allocation.process_id AND order_process_allocation.tenant_id = allocation.tenant_id WHERE allocation.deleted = 0 AND allocation.lifecycle_status = 'CURRENT' AND allocation.event_id IN
#{eventId}
ORDER BY allocation.event_id ASC, allocation.id ASC
